// Builds the Motion Gallery's lazy loaders and source listings from
// components/motion/items. The Preview tab renders each item's demo.tsx and
// the Code tab shows these same files, so the two cannot drift apart.
//
//   npm run motion:sources              write the generated files
//   npm run motion:sources -- --check   fail if they are out of date
//
// Shared helpers in components/motion/shared are listed with each component
// that imports them, with the import rewritten to a sibling file ('./name'),
// so the copied files work together in any folder.
import { readdir, readFile, writeFile, mkdir, rm } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const motion = path.join(root, 'components/motion');
const items = path.join(motion, 'items');
const shared = path.join(motion, 'shared');
const sourcesDir = path.join(motion, 'sources');
const loadersFile = path.join(motion, 'loaders.generated.ts');

const SHARED_IMPORT = /(['"])\.\.\/\.\.\/shared\/([\w-]+)\1/g;

async function sharedFor(code, seen) {
  const found = [];
  for (const [, , name] of code.matchAll(SHARED_IMPORT)) {
    if (seen.has(name)) continue;
    seen.add(name);
    const file = `${name}.ts`;
    const helper = await readFile(path.join(shared, file), 'utf8');
    found.push({ name: file, kind: 'helper', code: helper });
  }
  return found;
}

const localise = (code) =>
  code.replace(SHARED_IMPORT, (_, quote, name) => `${quote}./${name}${quote}`);

export async function collectSources() {
  const out = {};
  for (const slug of (await readdir(items)).sort()) {
    const dir = path.join(items, slug);
    const read = (file) => readFile(path.join(dir, file), 'utf8');
    const names = (await readdir(dir)).sort();
    const files = [
      {
        name: `${slug}.tsx`,
        kind: 'component',
        code: await read(`${slug}.tsx`),
      },
      { name: `${slug}.css`, kind: 'css', code: await read(`${slug}.css`) },
    ];
    for (const name of names) {
      if ([`${slug}.tsx`, `${slug}.css`, 'demo.tsx'].includes(name)) continue;
      files.push({ name, kind: 'helper', code: await read(name) });
    }
    const seen = new Set();
    for (const file of [...files])
      files.push(...(await sharedFor(file.code, seen)));
    out[slug] = {
      usage: await read('demo.tsx'),
      files: files.map((file) => ({ ...file, code: localise(file.code) })),
    };
  }
  return out;
}

function loaders(slugs) {
  const demos = slugs
    .map((s) => `  '${s}': lazy(() => import('./items/${s}/demo')),`)
    .join('\n');
  const sources = slugs
    .map(
      (s) =>
        `  '${s}': () =>\n    import('./sources/${s}.json').then((m) => m.default as MotionSource),`
    )
    .join('\n');
  return `// Generated by scripts/build-motion-sources.mjs. Do not edit by hand.
import { lazy, type ComponentType, type LazyExoticComponent } from 'react';
import type { MotionSource } from './types';

/** Each preview is its own chunk, fetched when its card first needs it. */
export const DEMOS: Record<string, LazyExoticComponent<ComponentType>> = {
${demos}
};

/** Source listings load only when a Code tab opens. */
export const SOURCES: Record<string, () => Promise<MotionSource>> = {
${sources}
};
`;
}

async function expected() {
  const all = await collectSources();
  const files = new Map();
  for (const [slug, source] of Object.entries(all))
    files.set(
      path.join(sourcesDir, `${slug}.json`),
      JSON.stringify(source, null, 2) + '\n'
    );
  files.set(loadersFile, loaders(Object.keys(all)));
  return files;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const files = await expected();
  if (process.argv.includes('--check')) {
    const stale = [];
    for (const [file, text] of files)
      if ((await readFile(file, 'utf8').catch(() => '')) !== text)
        stale.push(path.relative(root, file));
    const extra = (await readdir(sourcesDir).catch(() => [])).filter(
      (name) => !files.has(path.join(sourcesDir, name))
    );
    if (stale.length || extra.length) {
      console.error(
        `Motion sources are out of date (${[...stale, ...extra].join(', ')}). Run "npm run motion:sources".`
      );
      process.exit(1);
    }
    console.log(
      `Motion sources are up to date (${files.size - 1} components).`
    );
  } else {
    await rm(sourcesDir, { recursive: true, force: true });
    await mkdir(sourcesDir, { recursive: true });
    for (const [file, text] of files) await writeFile(file, text);
    console.log(`Wrote loaders and ${files.size - 1} source listings.`);
  }
}
